  ('b88bf080-3ca6-572a-bc37-5f7394cc17fa', null, (select id from public.skills where slug = 'write-g6-capitalization-punctuation'), null, 'hard',
   $q$Which sentence about the volunteers is punctuated correctly?$q$, $q$[{"text":"The volunteers who signed up first received green shirts, and the rest received blue ones.","is_correct":true},{"text":"The volunteers who signed up first, received green shirts and the rest received blue ones.","is_correct":false,"misconception_token":"comma-between-subject-verb"},{"text":"The volunteers, who signed up first, received green shirts, and the rest received blue ones.","is_correct":false,"misconception_token":"restrictive-clause-set-off"},{"text":"The volunteers who signed up, first received green shirts, and the rest received blue ones.","is_correct":false,"misconception_token":"comma-splits-clause"}]$q$::jsonb, $q$The volunteers who signed up first received green shirts, and the rest received blue ones.$q$, $q$"Who signed up first" tells which volunteers got green shirts, so it is needed and takes no commas, while the comma before "and" correctly joins the two complete clauses. Setting off "who signed up first" would mean all the volunteers signed up first, which contradicts "the rest received blue ones."$q$, 'draft', null)
